package com.example.repository;

import com.example.model.User;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

// Spring Data JPA abstraction providing repository methods automatically
public interface UserRepository extends JpaRepository<User, Long> {

    // Derived query method parsed by Spring Data JPA
    List<User> findByEmailAndActiveTrue(String email);

    // Explicit JPQL query utilizing Hibernate/JPA execution mechanics
    @Query("SELECT u FROM User u WHERE u.department.name = :deptName")
    List<User> findUsersByDepartmentName(@Param("deptName") String deptName);
}
